digest.description.source:
.input {$included :integer}
.match $included
one {{The {$issue} issue of a Cyris digest: {$included} article selected from {$received}.}}
* {{The {$issue} issue of a Cyris digest: {$included} articles selected from {$received}.}}

digest.source_items.source:
.input {$count :integer}
.match $count
one {{{$count} item from it in this issue}}
* {{{$count} items from it in this issue}}

mail.kept.source:
.input {$received :integer}
.input {$sources :integer}
.match $received $sources
one one {{Kept {$included} of {$received} article from {$sources} source.}}
one * {{Kept {$included} of {$received} article from {$sources} sources.}}
* one {{Kept {$included} of {$received} articles from {$sources} source.}}
* * {{Kept {$included} of {$received} articles from {$sources} sources.}}

mail.stats.source:
.input {$sources :integer}
.match $sources
one {{{$sources} source · {$received} received · {#b}{$included} included{/b}}}
* {{{$sources} sources · {$received} received · {#b}{$included} included{/b}}}

notify.link_health.source:
.input {$synthetic :integer}
.input {$dead :integer}
.match $synthetic $dead
one one {{{$synthetic} newsletter issue fetched with no canonical link; {$dead} item in this digest has no link to follow}}
one * {{{$synthetic} newsletter issue fetched with no canonical link; {$dead} items in this digest have no link to follow}}
* one {{{$synthetic} newsletter issues fetched with no canonical link; {$dead} item in this digest has no link to follow}}
* * {{{$synthetic} newsletter issues fetched with no canonical link; {$dead} items in this digest have no link to follow}}

onboarding.added_some.source:
.input {$failed :integer}
.match $failed
one {{Added {$added} of {$picked} feeds. This one was not added:}}
* {{Added {$added} of {$picked} feeds. These were not added:}}

onboarding.cards_empty.source:
.input {$count :integer}
.match $count
one {{No articles came back from this feed: {$names}. They stay in your sources and the first issue reads them again; check them under Sources in Settings.}}
* {{No articles came back from these {$count} feeds: {$names}. They stay in your sources and the first issue reads them again; check them under Sources in Settings.}}

onboarding.hour_needed.text:
.input {$which :string}
.match $which
morning {{請為「早上發布」填入 0 到 23 的整點。}}
evening {{請為「晚上發布」填入 0 到 23 的整點。}}
* {{請為「早上發布」和「晚上發布」填入 0 到 23 的整點。}}

onboarding.hour_needed.source:
.input {$which :string}
.match $which
morning {{Morning needs a whole hour from 0 to 23.}}
evening {{Evening needs a whole hour from 0 to 23.}}
* {{Morning and Evening need a whole hour from 0 to 23.}}

onboarding.recorded_votes.source:
.input {$count :integer}
.match $count
one {{Recorded 1 vote: {$up} interested, {$down} not interested.}}
* {{Recorded {$count} votes: {$up} interested, {$down} not interested.}}

onboarding.votes_gone.source:
.input {$count :integer}
.match $count
one {{1 article has left its feed since the cards were dealt, so that vote was not recorded.}}
* {{{$count} articles have left its feed since the cards were dealt, so that vote was not recorded.}}

raw.label.source:
.input {$articles :integer}
.input {$sources :integer}
.match $articles $sources
one one {{All articles · {$articles} article · {$sources} source}}
one * {{All articles · {$articles} article · {$sources} sources}}
* one {{All articles · {$articles} articles · {$sources} source}}
* * {{All articles · {$articles} articles · {$sources} sources}}

settings.hours_need.source:
.input {$count :integer}
.match $count
one {{{$names} needs a whole hour from 0 to 23.}}
* {{{$names} need a whole hour from 0 to 23.}}

settings_api.test_mail_sent.text:
.input {$status :string}
.match $status
delivered {{測試信已送達 {$recipient}。}}
queued {{寄給 {$recipient} 的測試信已排入佇列。}}
* {{寄給 {$recipient} 的測試信：{$status}。}}
